cypress_script:
describe('Numeric Input Field Tests', () => {
  it('should accept a valid number', () => {
    cy.visit('https://the-internet.herokuapp.com/inputs');
    cy.get('input[type="number"]').type('123').should('have.value', '123');
  });
  it('should not change URL when invalid input is provided', () => {
    cy.visit('https://the-internet.herokuapp.com/inputs');
    cy.get('input[type="number"]').type('abc');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/inputs');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

 test.describe('Numeric Input Field Tests', () => {
   test('should accept a valid number', async ({ page }) => {
     await page.goto('https://the-internet.herokuapp.com/inputs');
     await page.fill('input[type="number"]', '123');
     const value = await page.inputValue('input[type="number"]');
     expect(value).toBe('123');
   });
   test('should not change URL when invalid input is provided', async ({ page }) => {
     await page.goto('https://the-internet.herokuapp.com/inputs');
     await page.fill('input[type="number"]', 'abc');
     expect(page.url()).toBe('https://the-internet.herokuapp.com/inputs');
   });
 });
